Step 4 — GSEA per cell type
Where ORA throws away the ranking, GSEA uses it. Build a named, decreasing-sorted vector of log2FoldChanges for each cell type and run gseGO:

run_gseGO &lt;- function(ct, df) {
  sub &lt;- df |&gt;
    filter(celltype == ct, !is.na(ENTREZID)) |&gt;
    arrange(desc(log2FoldChange)) |&gt;
    distinct(ENTREZID, .keep_all = TRUE)

  rk &lt;- setNames(sub$log2FoldChange, sub$ENTREZID)

  gse &lt;- gseGO(
    geneList      = rk,
    OrgDb         = org.Hs.eg.db,
    ont           = "BP",
    keyType       = "ENTREZID",
    pAdjustMethod = "BH",
    pvalueCutoff  = 0.05,
    eps           = 0,
    verbose       = FALSE
  )
  gse@result$celltype &lt;- ct
  gse
}

# This may take 1-3 minutes per cell type
gse_list &lt;- map(unique(de_mapped$celltype), run_gseGO, df = de_mapped) |&gt;
  set_names(unique(de_mapped$celltype)) |&gt;
  compact()

# Top GSEA hits per cell type, ranked by NES (Normalized Enrichment Score)
map_dfr(names(gse_list),
        \(ct) gse_list[[ct]]@result |&gt;
              arrange(desc(NES)) |&gt;
              head(5) |&gt;
              mutate(celltype = ct) |&gt;
              select(celltype, Description, NES, p.adjust))

A classic GSEA “running enrichment” plot for a single term in a single cell type:

# Pick a cell type and a known interesting term
ct_pick &lt;- "CD14 Mono"
if (!is.null(gse_list[[ct_pick]])) {
  gseaplot2(gse_list[[ct_pick]],
            geneSetID = head(gse_list[[ct_pick]]@result$ID, 3),
            title     = paste0(ct_pick, " — top 3 BP enrichments"))
}

B.5 — Run DESeq2 per cell type

run_de &lt;- function(ct) {
  keep &lt;- meta_pb$celltype == ct
  if (sum(keep) &lt; 4 || length(unique(meta_pb$condition[keep])) &lt; 2) return(NULL)

  dds &lt;- DESeqDataSetFromMatrix(
    countData = pb[, keep],
    colData   = as.data.frame(meta_pb[keep, ]),
    design    = ~ condition
  )
  dds &lt;- DESeq(dds, quiet = TRUE)

  res &lt;- results(dds, contrast = c("condition","STIM","CTRL"))
  res &lt;- lfcShrink(dds, coef = "condition_STIM_vs_CTRL",
                   res = res, type = "apeglm")

  as.data.frame(res) |&gt;
    rownames_to_column("gene") |&gt;
    mutate(celltype = ct)
}

de_all &lt;- map_dfr(unique(meta_pb$celltype), run_de) |&gt;
  filter(!is.na(padj))
glimpse(de_all)

Step 1 — Define donor / sample IDs
Like Tutorial 06’s pseudobulk DE, miloR needs biological replicates within each condition. The muscData::Kang18_8vs8() loader from Tutorial 01 carries the real donor IDs in the ind column, so we use the eight real donors as replicates. A synthetic-donor fallback is kept only for objects that somehow arrive without donor metadata.

# Real donors (column `ind`, from the muscData loader) are the biological
# replicates. Fall back to synthetic pseudo-donors only if no donor column is
# present (e.g. an older SeuratData `ifnb`).
if (!"donor" %in% colnames(ifnb@meta.data)) {
  if ("ind" %in% colnames(ifnb@meta.data)) {
    ifnb$donor &lt;- ifnb$ind
  } else {
    ifnb$donor &lt;- paste0(ifnb$stim, "_d",
                         sample(1:4, size = ncol(ifnb), replace = TRUE))
  }
}

# miloR needs a single per-cell sample ID. Combine donor + stim:
ifnb$sample &lt;- paste(ifnb$donor, ifnb$stim, sep = "_")
table(ifnb$sample, ifnb$stim)







Warning



On the real ind donors — the default with the Tutorial 01 loader — the test is valid. The synthetic-donor fallback only triggers when no donor metadata is present; on synthetic donors the neighbourhood SpatialFDRs are not biologically meaningful, so you’ll see the workflow run correctly but should not interpret them as real findings.

Step 1 — Load data and metadata

